/* @lc app=leetcode id=3342 lang=kotlin */ class Solution { fun minTimeToReach(moveTime: Array<IntArray>): Int = moveTime.size.let { n -> moveTime[0].size.let { m -> LongArray(n * m * 2) { Long.MAX_VALUE }.also { it[0] = 0L }.let { d -> java.util.PriorityQueue<LongArray>(compareBy<LongArray> { it[0] }).also { it.add(longArrayOf(0L, 0L)) }.let { pq -> generateSequence { pq.poll() }.filter { (t, s) -> t == d[s.toInt()] }.forEach { (t, s) -> (s.toInt() / 2).let { c -> (s % 2).toInt().let { p -> listOf(c / m + 1 to c % m, c / m - 1 to c % m, c / m to c % m + 1, c / m to c % m - 1).filter { (a, b) -> a in 0 until n && b in 0 until m }.forEach { (a, b) -> (maxOf(t, moveTime[a][b].toLong()) + 1 + p).let { nt -> ((a * m + b) * 2 + 1 - p).let { ns -> if (nt < d[ns]) pq.add(longArrayOf(nt, ns.toLong())).also { d[ns] = nt } } } } } } }.let { minOf(d[(n * m - 1) * 2], d[(n * m - 1) * 2 + 1]).toInt() } } } } } }